// Prepare context for dev_patch agent
const input = $input.item.json;

const chatInput = [
  `[DEV_PATCH AGENT] Task: ${input.task_kind}`,
  `Run ID: ${input.run_id}`,
  input.story_id ? `Story ID: ${input.story_id}` : null,
  `Risk Profile: ${input.risk_profile}`,
  `Context Profile: ${input.context_profile}`,
  '',
  'Previous pipeline results:',
  JSON.stringify(input.previous_results || [], null, 2),
  '',
  'Instructions:',
  '1. Search knowledge base for relevant patterns and rules',
  '2. Analyze the task and propose code changes',
  '3. Generate a patch (file changes) following project conventions',
  '4. Create a branch on GitHub and commit changes',
  '5. Return: { branch, files_modified, patch_summary }'
].filter(Boolean).join('\n');

return {
  json: {
    chatInput,
    run_id: input.run_id,
    story_id: input.story_id,
    task_kind: input.task_kind,
    agent_slug: 'dev_patch',
    session_id: `dev-patch-${input.run_id}`
  }
};

// Build the final dev_patch result
const agentResult = $('Dev Patch Agent').item.json;
const branchResult = $('Create Branch').item.json;

return {
  json: {
    agent_slug: 'dev_patch',
    branch: branchResult.branch || `aisha/dev-patch-${$('Prepare Dev Context').item.json.run_id?.substring(0, 8)}`,
    files_modified: agentResult.files_modified || [],
    patch_summary: agentResult.output || agentResult.text || 'Patch generated',
    passed: true
  }
};
